var _FUNCS={ abs:Math.abs, sqrt:Math.sqrt, min:Math.min, max:Math.max,
  floor:Math.floor, ceil:Math.ceil, round:Math.round, log:Math.log, exp:Math.exp,
  sin:Math.sin, cos:Math.cos, tan:Math.tan };
var _CONSTS={ pi:Math.PI, e:Math.E };
function exprTokenize(src){
  var out=[], i=0, s=String(src);
  while(i<s.length){
    var c=s[i];
    if(c===' '||c==='\t'||c==='\n'){ i++; continue; }
    if(c>='0'&&c<='9'||c==='.'){
      var j=i;
      while(j<s.length&&(s[j]>='0'&&s[j]<='9'||s[j]==='.')) j++;
      var num=parseFloat(s.slice(i,j));
      if(isNaN(num)) return {value:null, error:'非法数字 at '+i};
      out.push({t:'num', v:num}); i=j; continue;
    }
    if(/[a-zA-Z_]/.test(c)){
      var k=i;
      while(k<s.length&&/[a-zA-Z_0-9]/.test(s[k])) k++;
      out.push({t:'name', v:s.slice(i,k)}); i=k; continue;
    }
    if('+-*/%^(),'.indexOf(c)>=0){ out.push({t:c, v:c}); i++; continue; }
    return {value:null, error:'非法字符 '+c+' at '+i};
  }
  return {value:out, error:null};
}
var _PREC={'+':1,'-':1,'*':2,'/':2,'%':2,'^':3,'neg':4};
var _RIGHT={'^':1,'neg':1};
function exprToRpn(tokens){
  var out=[], ops=[], prev=null;
  for(var i=0;i<tokens.length;i++){
    var tk=tokens[i];
    if(tk.t==='num'){ out.push(tk); }
    else if(tk.t==='name'){
      if(i+1<tokens.length&&tokens[i+1].t==='('){ ops.push({t:'func', v:tk.v}); }
      else out.push({t:'var', v:tk.v});
    }
    else if(tk.t===','){
      while(ops.length&&ops[ops.length-1].t!=='(') out.push(ops.pop());
      if(!ops.length) return {value:null, error:'逗号位置非法'};
    }
    else if(tk.t==='('){ ops.push(tk); }
    else if(tk.t===')'){
      while(ops.length&&ops[ops.length-1].t!=='(') out.push(ops.pop());
      if(!ops.length) return {value:null, error:'括号不匹配'};
      ops.pop();
      if(ops.length&&ops[ops.length-1].t==='func') out.push(ops.pop());
    }
    else {
      var op=tk.t;
      if(op==='-'&&(prev===null||prev.t==='('||prev.t===','||_PREC[prev.t]||prev.t==='neg')) op='neg';
      while(ops.length){
        var top=ops[ops.length-1];
        if(top.t==='('||top.t==='func') break;
        var tp=_PREC[top.t], cp=_PREC[op];
        if(tp>cp||(tp===cp&&!_RIGHT[op])) out.push(ops.pop());
        else break;
      }
      ops.push({t:op, v:op});
    }
    prev=tk;
  }
  while(ops.length){
    var rest=ops.pop();
    if(rest.t==='(') return {value:null, error:'括号不匹配'};
    out.push(rest);
  }
  return {value:out, error:null};
}
var _ARITY={ abs:1, sqrt:1, floor:1, ceil:1, round:1, log:1, exp:1, sin:1, cos:1, tan:1, min:2, max:2 };
function exprEvalRpn(rpn, vars){
  vars=vars||{};
  var st=[];
  for(var i=0;i<rpn.length;i++){
    var tk=rpn[i];
    if(tk.t==='num'){ st.push(tk.v); }
    else if(tk.t==='var'){
      if(vars.hasOwnProperty(tk.v)){ st.push(Number(vars[tk.v])); }
      else if(_CONSTS.hasOwnProperty(tk.v)){ st.push(_CONSTS[tk.v]); }
      else return {value:null, error:'未定义变量 '+tk.v};
    }
    else if(tk.t==='func'){
      var f=_FUNCS[tk.v];
      if(!f) return {value:null, error:'未知函数 '+tk.v};
      var arity=_ARITY[tk.v];
      if(st.length<arity) return {value:null, error:'函数 '+tk.v+' 参数不足'};
      var args=st.splice(st.length-arity, arity);
      st.push(f.apply(null, args));
    }
    else if(tk.t==='neg'){
      if(st.length<1) return {value:null, error:'一元负号缺操作数'};
      st.push(-st.pop());
    }
    else {
      if(st.length<2) return {value:null, error:'操作符 '+tk.t+' 缺操作数'};
      var b=st.pop(), a=st.pop(), r;
      switch(tk.t){
        case '+': r=a+b; break;
        case '-': r=a-b; break;
        case '*': r=a*b; break;
        case '/': if(b===0) return {value:null, error:'除以零'}; r=a/b; break;
        case '%': if(b===0) return {value:null, error:'模零'}; r=a%b; break;
        case '^': r=Math.pow(a,b); break;
        default: return {value:null, error:'未知操作符 '+tk.t};
      }
      st.push(r);
    }
  }
  if(st.length!==1) return {value:null, error:'表达式不完整'};
  return {value:st[0], error:null};
}
function exprEval(src, vars){
  var t=exprTokenize(src);
  if(t.error) return t;
  if(!t.value.length) return {value:null, error:'空表达式'};
  var r=exprToRpn(t.value);
  if(r.error) return r;
  return exprEvalRpn(r.value, vars);
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { exprTokenize:exprTokenize, exprToRpn:exprToRpn, exprEvalRpn:exprEvalRpn, exprEval:exprEval };
}
if (typeof window !== 'undefined') {
  window.ExprForgePure = { exprTokenize:exprTokenize, exprToRpn:exprToRpn, exprEvalRpn:exprEvalRpn, exprEval:exprEval };
}
